void Engine::unlink(int slot) {
    auto &o = orders[slot];
    auto &l = levels[o.side][o.price];
    if (o.prev >= 0)
        orders[o.prev].next = o.next;
    else
        l.head = o.next;
    if (o.next >= 0)
        orders[o.next].prev = o.prev;
    else
        l.tail = o.prev;
    l.count--;
    l.volume -= o.qty;
    if (l.count == 0)
        bits_[o.side][o.price / 64] &= ~(std::uint64_t(1) << (o.price % 64));
    o.prev = o.next = -1;
}

